function showTab(evt, id) {

  document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');

  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));

  document.getElementById(id).style.display = 'block';

  evt.currentTarget.classList.add('active');

}



document.addEventListener('DOMContentLoaded', () => {

  const basePrice = 1500; 

  const baseProductName = 'Art&Air Acoustic Cable';

  const baseCablePrice = 200; 

  const priceIncrementPer50cm = baseCablePrice * 0.15; 



  const priceEl = document.getElementById('main-price');

  const nameEl = document.getElementById('tilda-product-name');



  function updateCartData() {

    let totalOptionsPrice = 0;

    let selectedOptions = [];



    document.querySelectorAll('.price-item:checked').forEach(checkedItem => {

      totalOptionsPrice += parseInt(checkedItem.getAttribute('data-price'), 10) || 0;

      let optionText = checkedItem.parentElement.textContent.trim();



      let cleanText = optionText.replace('Stock: ', '');

      selectedOptions.push(cleanText);

    });



    const selectedCableTypeEl = document.querySelector('input[name="cable-len-type"]:checked');

    const selectedCableType = selectedCableTypeEl ? selectedCableTypeEl.value : 'standard';



    if (selectedCableType === 'custom') {

      document.getElementById('slider-wrapper').style.display = 'block'; 

      let currentLength = parseFloat(document.getElementById('length-slider').value);

      document.getElementById('length-display').innerText = currentLength.toFixed(1);



      let extraSteps = currentLength > 2.0 ? Math.round((currentLength - 2.0) / 0.5) : 0;

      let extraLengthCost = extraSteps * priceIncrementPer50cm;



      document.getElementById('length-price-display').innerText = extraLengthCost; 

      totalOptionsPrice += extraLengthCost; 



      if (currentLength !== 2.0) {

          selectedOptions.push(`Length: ${currentLength.toFixed(1)}m`);

      }

    } else {

      document.getElementById('slider-wrapper').style.display = 'none'; 

      document.getElementById('length-price-display').innerText = "0";

      document.getElementById('length-slider').value = "2.0"; 

    }



    if (priceEl) {

        priceEl.innerText = basePrice + totalOptionsPrice;

    }



    if (nameEl) {

        nameEl.innerText = selectedOptions.length > 0 ? `${baseProductName} [${selectedOptions.join(' | ')}]` : `${baseProductName} (Standard 2.0m)`;

    }

  }



  document.querySelectorAll('.price-item, input[name="cable-len-type"], #length-slider').forEach(el => el.addEventListener('change', updateCartData));

  document.getElementById('length-slider').addEventListener('input', updateCartData);



  updateCartData();



const buyBtn = document.querySelector('.buy-btn');

  if (buyBtn) {
    buyBtn.addEventListener('click', function() {
      // Отправка события в Google Analytics 4
      if (typeof gtag === 'function') {
        gtag('event', 'buy_now_click', {
          'event_category': 'ecommerce',
          'event_label': 'Button Buy Now',
          'value': parseInt(priceEl.innerText) || basePrice
        });
      }
    });
  }
  // ==========================================

});

