  /* FILIN LABS — unified font for the whole product block */
  .js-product,
  .js-product *,
  .js-product *::before,
  .js-product *::after {
    font-family: 'Montserrat', Arial, sans-serif !important;
  }

  .purchase-container { text-align: center; margin: 20px 0; padding: 20px; background: #fffbf7; border-radius: 8px; }
  .purchase-container .price-title { margin: 0 0 15px 0; color: #333; font-size: 24px; font-weight: bold; }
  .buy-btn {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100vw;
    min-height: 144px;
    margin-left: calc(50% - 50vw);
    box-sizing: border-box;
    overflow: hidden;
    text-decoration: none;
    padding: 26px 46px;
    font-size: 34.125px; /* +25% к предыдущему размеру */
    line-height: 1;
    letter-spacing: .025em;
    background:
      linear-gradient(115deg,
        #81572f 0%,
        #a97543 14%,
        #c59661 31%,
        #e3c28f 45%,
        #f1d6a7 50%,
        #d4a66d 58%,
        #a97543 78%,
        #81572f 100%);
    background-size: 240% 100%;
    background-position: 0% 50%;
    color: #ffffff !important;
    border: 2px solid #7b522c;
    cursor: pointer;
    text-transform: uppercase;
    font-weight: 800;
    border-radius: 0;
    box-shadow:
      inset 0 0 0 1px rgba(255,255,255,.70),
      inset 0 0 0 5px rgba(115,72,34,.30),
      inset 0 0 0 7px rgba(255,231,193,.34),
      inset 0 1px 14px rgba(255,255,255,.18),
      inset 0 -8px 20px rgba(78,44,17,.16),
      0 9px 26px rgba(67,42,21,.20),
      0 0 28px rgba(196,143,82,.12);
    transition:
      filter .25s ease,
      box-shadow .25s ease;
    animation:
      buyLuxuryShimmer 6.8s ease-in-out infinite,
      buyLuxuryGlow 5.6s ease-in-out infinite;
    isolation: isolate;
  }

  /* Decorative inner luxury frame */
  .buy-btn::before {
    content: "";
    position: absolute;
    inset: 10px 14px;
    border: 1px solid rgba(255,247,229,.76);
    box-shadow:
      0 0 0 2px rgba(111,68,31,.34),
      inset 0 0 0 1px rgba(255,225,179,.34),
      inset 0 0 18px rgba(255,255,255,.08);
    pointer-events: none;
    z-index: 1;
  }

  /* Moving specular highlight across the entire button */
  .buy-btn::after {
    content: "";
    position: absolute;
    top: -55%;
    left: -26%;
    width: 18%;
    height: 220%;
    background: linear-gradient(
      90deg,
      transparent 0%,
      rgba(255,255,255,.06) 20%,
      rgba(255,255,255,.64) 50%,
      rgba(255,255,255,.10) 80%,
      transparent 100%
    );
    transform: rotate(16deg);
    filter: blur(.2px);
    pointer-events: none;
    z-index: 2;
    animation: buyLuxurySweep 6.2s ease-in-out infinite;
  }

  .buy-btn-label {
    position: relative;
    z-index: 3;
    display: inline-block;
    color: #fff;
    text-align: center;
    text-shadow:
