  .options-list { display: flex; flex-direction: column; align-items: flex-start; margin-top: 10px; max-width: 650px; margin-left: auto; margin-right: auto; }
  .options-list label { font-family: 'Montserrat', sans-serif; font-size: 16px; cursor: pointer; display: flex; align-items: center; gap: 15px; margin-bottom: 12px; width: 100%; padding: 12px 15px; background: #fffbf7; border: 1px solid #f0e6d9; border-radius: 6px; transition: background 0.2s ease; }
  .options-list label:hover { background: #fdf5eb; }
  input[type="radio"], input[type="checkbox"] { width: 18px; height: 18px; flex-shrink: 0; cursor: pointer; margin: 0; accent-color: #b38b59; }
  .purchase-container { text-align: center; margin: 20px 0; padding: 20px; background: #fffbf7; border-radius: 8px; font-family: 'Montserrat', sans-serif; }
  .purchase-container .price-title { margin: 0 0 15px 0; color: #333; font-size: 24px; font-weight: bold; }
  .buy-btn { display: inline-block; text-decoration: none; padding: 15px 30px; font-size: 18px; background-color: #b38b59; color: #ffffff !important; border: none; cursor: pointer; text-transform: uppercase; font-weight: bold; border-radius: 4px; transition: 0.3s; font-family: 'Montserrat', sans-serif; }
  .buy-btn:hover { background-color: #926f43; color: #ffffff !important; }
  .tabs-wrapper { width: 100%; box-sizing: border-box; font-family: 'Montserrat', sans-serif; }
.tabs-header { display: flex; border-bottom: 2px solid #eee; flex-wrap: wrap; }
.tab-btn { padding: 20px 15px; border: none; background: transparent; font-weight: bold; cursor: pointer; color: #888; text-transform: uppercase; font-size: 15px; flex: 1; min-width: 140px; transition: all 0.2s ease; font-family: 'Montserrat', sans-serif; }
  .tab-btn.active { border-bottom: 2px solid #b38b59; color: #b38b59; }
  .content-container { padding: 20px 25px; text-align: left; max-width: 1200px; margin: 0 auto; }
  .description-content p { margin-top: 0; margin-bottom: 15px; line-height: 1.6; }
  .description-content h3 { margin-top: 30px; margin-bottom: 15px; border-left: 3px solid #b38b59; padding-left: 10px; font-size: 18px; color: #333; }
  .tab-content { width: 100%; }
  .specs-table { width: 100%; max-width: 800px; margin: 20px auto; border-collapse: collapse; }
  .specs-table td { padding: 15px; border-bottom: 1px solid #eee; font-size: 16px; }
