  .buy-btn { display: inline-block; text-decoration: none; padding: 15px 30px; font-size: 18px; background-color: #b38b59; color: #ffffff !important; border: none; cursor: pointer; text-transform: uppercase; font-weight: bold; border-radius: 4px; transition: 0.3s; }

  .buy-btn:hover { background-color: #926f43; color: #ffffff !important; }

  .tabs-wrapper { width: 100%; box-sizing: border-box; font-family: 'Montserrat', sans-serif; }

.tabs-header { display: flex; border-bottom: 2px solid #eee; flex-wrap: wrap; }
  .tab-btn { padding: 20px 15px; border: none; background: transparent; font-weight: bold; cursor: pointer; color: #888; text-transform: uppercase; font-size: 16px; flex: 1; min-width: 150px; }

  .tab-btn.active { border-bottom: 2px solid #b38b59; color: #b38b59; }

  .content-container { padding: 20px 25px; text-align: left; max-width: 1200px; margin: 0 auto; }

