  .tabs-wrapper { 
    width: 100%; 
    box-sizing: border-box; 
    font-family: 'Montserrat', sans-serif;
  }

.tabs-header { display: flex; border-bottom: 2px solid #eee; flex-wrap: wrap; }  
  .tab-btn { 
    flex: 1; 
    padding: 25px; 
    border: none; 
    background: transparent; 
    font-weight: bold; 
    cursor: pointer; 
    color: #888;
    text-transform: uppercase;
    font-size: 22px;
  }

  .tab-btn.active { border-bottom: 2px solid #b38b59; color: #b38b59; }

  /* Основной контейнер с отступами 25px */
  .content-container {
    padding: 20px 25px; /* Отступы по бокам */
    text-align: left;   /* Текст аккуратно выровнен по левому краю */
    max-width: 1200px;  /* Чтобы текст не был слишком широким на огромных мониторах */
    margin: 0 auto;
  }

  .content-container h3 { margin: 30px 0 15px 0; }
  .content-container p { font-size: 18px; line-height: 1.6; margin-bottom: 15px; }

  /* Красивый список */
  .bullet-list { margin: 15px 0; padding-left: 20px; font-size: 18px; line-height: 1.6; }
  .bullet-list li { margin-bottom: 8px; }

  .tab-content { width: 100%; }

  .specs-table { 
    width: 100%;            /* Таблица занимает доступное место */
    max-width: 800px;       /* Ограничиваем ширину, чтобы не была слишком широкой */
    margin: 20px auto;      /* Центрируем таблицу по горизонтали */
    border-collapse: collapse; 
  }

  .specs-table td { 
    padding: 15px; 
    border-bottom: 1px solid #eee; 
    font-size: 18px; 
  }

function showTab(evt, id) {
  document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById(id).style.display = 'block';
  evt.currentTarget.classList.add('active');
}
