  .purchase-container { text-align: center; margin: 20px 0; padding: 20px; background: #fffbf7; border-radius: 8px; }
  .purchase-container .price-title { margin: 0 0 15px 0; color: #333; font-size: 24px; font-weight: bold; }
  .buy-btn { display: inline-block; text-decoration: none; padding: 15px 30px; font-size: 18px; background-color: #b38b59; color: #ffffff !important; border: none; cursor: pointer; text-transform: uppercase; font-weight: bold; border-radius: 4px; transition: 0.3s; }
  .buy-btn:hover { background-color: #926f43; color: #ffffff !important; }

  /* БЛОК PERFECT MATCHES (КОМПАКТНЫЕ ПОЛЯ) */
  .perfect-matches-block {
    margin: 35px auto 0 auto;
    max-width: 860px;
    width: 100%;
    box-sizing: border-box;
    padding: 25px;
    background: #ffffff;
    border: 1px solid #ebd9c5;
    border-radius: 8px;
    text-align: center;
    box-shadow: 0 4px 15px rgba(0,0,0,0.03);
  }
  .pm-title {
    margin: 0 0 10px 0;
    font-size: 22px;
    color: #b38b59;
    font-weight: 700;
    text-transform: uppercase;
  }
  .pm-desc {
    font-size: 15px;
    margin: 0 auto 20px auto;
    color: #555;
    max-width: 700px;
    line-height: 1.5;
  }
  .pm-formula {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-weight: 600;
    flex-wrap: wrap;
  }
  .pm-item {
    display: flex;
    align-items: center;
    gap: 8px;
