  .options-list { display: flex; flex-direction: column; align-items: flex-start; margin-top: 20px; max-width: 500px; margin-left: auto; margin-right: auto; }
  .options-list label { font-size: 18px; cursor: pointer; width: 100%; display: flex; align-items: flex-start; gap: 15px; margin-bottom: 10px; }
  input[type="checkbox"], input[type="radio"] { width: 20px; height: 20px; flex-shrink: 0; cursor: pointer; margin: 4px 0 0 0; }

  @media screen and (max-width: 1240px) {
    .perfect-matches-block {
      max-width: 95%;
    }
  }

function showTab(evt, id) {
  document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById(id).style.display = 'block';
  evt.currentTarget.classList.add('active');
}

document.addEventListener('DOMContentLoaded', () => {
  const basePrice = 2500;
  const baseProductName = 'Filin Audio Limited Isodynamic Closed Headphones';
  const priceIncrementPer10cm = 0;
  const priceEl = document.getElementById('main-price');
  const nameEl = document.getElementById('tilda-product-name');
  const discountMsg = document.getElementById('bundle-discount-msg');

  const radioInputs = document.querySelectorAll('input[name="cable-type"]');
  const sliderWrapper = document.getElementById('slider-wrapper');
  const lengthSlider = document.getElementById('length-slider');
  const lengthDisplay = document.getElementById('length-display');
  const lengthPriceDisplay = document.getElementById('length-price-display');

  function updateCartData() {
    let totalOptionsPrice = 0;
    let selectedOptions = [];

    let bundleItems = document.querySelectorAll('.bundle-item');
    let allBundleChecked = bundleItems.length > 0;

    bundleItems.forEach(item => {
      if (!item.checked) allBundleChecked = false;
    });

    document.querySelectorAll('.price-item:checked').forEach(checkedItem => {
      totalOptionsPrice += parseInt(checkedItem.getAttribute('data-price'), 10) || 0;
      let optionText = checkedItem.parentElement.textContent.trim();
      if(optionText !== "Stock: No options" && !optionText.startsWith("Stock:")) {
         selectedOptions.push(optionText);
      }
    });

    const selectedRadio = document.querySelector('input[name="cable-type"]:checked');
    const selectedCableType = selectedRadio ? selectedRadio.value : 'standard';

    if (selectedCableType === 'custom') {
      sliderWrapper.style.display = 'block';
      let currentLength = parseFloat(lengthSlider.value);
      lengthDisplay.innerText = currentLength.toFixed(1);
      let extraSteps = Math.round((currentLength - 2.0) / 0.1);
      let extraLengthCost = extraSteps * priceIncrementPer10cm;
      lengthPriceDisplay.innerText = extraLengthCost;
      totalOptionsPrice += extraLengthCost;
      if (extraSteps > 0) {
        selectedOptions.push(`Custom Cable Length: ${currentLength.toFixed(1)}m`);
      }
    } else {
      sliderWrapper.style.display = 'none';
      lengthPriceDisplay.innerText = "0";
      lengthSlider.value = "2.0";
    }

    let finalPrice = basePrice + totalOptionsPrice;
    let bundleDiscountText = "";

    if (allBundleChecked) {
      finalPrice = Math.round(finalPrice * 1);
      bundleDiscountText = " (5% Bundle Discount for Each Added item was applied)";
      if (discountMsg) {
        discountMsg.classList.add('active-discount');
        discountMsg.innerHTML = "<b>5% Bundle Discount</b> for Each Added item was successfully applied to total!";
      }
    } else {
      if (discountMsg) {
        discountMsg.classList.remove('active-discount');
        discountMsg.innerHTML = "Add recommended synergy components to get <b>5% OFF</b> per each item added.";
      }
    }

    if (priceEl) priceEl.innerText = finalPrice;

    if (nameEl) {
      if (selectedOptions.length > 0) {
        nameEl.innerText = baseProductName + " [" + selectedOptions.join(' | ') + "]" + bundleDiscountText;
      } else {
        nameEl.innerText = baseProductName + bundleDiscountText;
      }
    }
  }

