  .purchase-container { text-align: center; margin: 20px 0; padding: 20px; background: #fffbf7; border-radius: 8px; }

  .purchase-container .price-title { margin: 0 0 15px 0; color: #333; font-size: 24px; font-weight: bold; }

  .buy-btn { 
    display: inline-block; 
    text-decoration: none; 
    padding: 15px 30px; 
    font-size: 18px; 
    background-color: #b38b59; 
    color: #ffffff !important; 
    border: none; 
    cursor: pointer; 
    text-transform: uppercase; 
    font-weight: bold; 
    border-radius: 4px; 
    transition: 0.3s; 
  }
  .buy-btn:hover { 
    background-color: #926f43; 
    color: #ffffff !important; 
  }

  /* БЛОК PERFECT MATCHES (КОМПАКТНЫЕ ПОЛЯ) */
  .perfect-matches-block {
    margin: 35px auto 0 auto;
    max-width: 860px;
    width: 100%;
    box-sizing: border-box;
    padding: 25px;
    background: #ffffff;
    border: 1px solid #ebd9c5;
    border-radius: 8px;
    text-align: center;
    box-shadow: 0 4px 15px rgba(0,0,0,0.03);
  }
  .pm-title {
    margin: 0 0 10px 0;
    font-size: 22px;
    color: #b38b59;
    font-weight: 700;
    text-transform: uppercase;
  }
  .pm-desc {
    font-size: 15px;
    margin: 0 auto 20px auto;
    color: #555;
    max-width: 700px;
    line-height: 1.5;
  }
  .pm-formula {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-weight: 600;
    flex-wrap: wrap;
  }
  .pm-item {
    display: flex;
    align-items: center;
    gap: 8px;
    background: #fffbf7;
    padding: 12px 18px;
    border-radius: 6px;
    border: 1px solid #e0cbae;
    transition: all 0.2s;
    cursor: pointer;
  }

  .pm-item a {
    color: #666666 !important;
    text-decoration: none !important;
  }
  .pm-item a:hover {
    color: #b38b59 !important;
  }

  .pm-item:hover {
    border-color: #b38b59;
    background: #fff;
  }
  .pm-base {
    background: #f0f0f0;
    border-color: #dcdcdc;
    color: #666;
    cursor: default;
  }
  .pm-base:hover {
    border-color: #dcdcdc;
    background: #f0f0f0;
  }
  .pm-plus, .pm-equals {
    font-size: 24px;
    color: #a0a0a0;
  }
  .pm-result {
    color: #fff;
    background: #b38b59;
    padding: 12px 20px;
    border-radius: 6px;
    font-style: normal;
    letter-spacing: 0.5px;
  }
  .pm-discount {
    margin-top: 20px;
    font-size: 15px;
    color: #333;
    padding: 10px;
    background: #fdf5ec;
    display: inline-block;
    border-radius: 4px;
    border-left: 3px solid #b38b59;
  }
  .pm-discount.active-discount {
    background: #e8f5e9;
    border-left-color: #4caf50;
    color: #2e7d32;
  }

  .tabs-wrapper { width: 100%; box-sizing: border-box; font-family: 'Montserrat', sans-serif; }
  .tabs-header { display: flex; border-bottom: 2px solid #eee; flex-wrap: wrap; }
  .tab-btn { padding: 20px 15px; border: none; background: transparent; font-weight: bold; cursor: pointer; color: #888; text-transform: uppercase; font-size: 16px; flex: 1; min-width: 150px; }
  .tab-btn.active { border-bottom: 2px solid #b38b59; color: #b38b59; }
  .content-container { padding: 20px 25px; text-align: left; max-width: 1200px; margin: 0 auto; }

  .description-content p { margin-top: 0; margin-bottom: 15px; line-height: 1.6; }
  .description-content h3 { margin-top: 30px; margin-bottom: 15px; }
  .description-content ul { line-height: 1.6; padding-left: 20px; }
  .description-content li { margin-bottom: 8px; }

  .tab-content { width: 100%; }
  .specs-table { width: 100%; max-width: 800px; margin: 20px auto; border-collapse: collapse; }
  .specs-table td { padding: 15px; border-bottom: 1px solid #eee; font-size: 18px; }
  .options-list { display: flex; flex-direction: column; align-items: flex-start; margin-top: 20px; max-width: 500px; margin-left: auto; margin-right: auto; }
  .options-list label { font-size: 18px; cursor: pointer; width: 100%; display: flex; align-items: flex-start; gap: 15px; margin-bottom: 10px; }

  .stage-split { display: flex; justify-content: center; gap: 80px; margin-top: 20px; }
  .stage-split label { font-size: 18px; cursor: pointer; display: flex; align-items: center; gap: 15px; }

  /* Единый стиль для чекбоксов и радиокнопок */
  input[type="checkbox"], input[type="radio"] { 
    width: 20px; 
    height: 20px; 
    flex-shrink: 0; 
    cursor: pointer; 
    margin: 4px 0 0 0; 
  }

  .version-btn {
    display: inline-block;
    text-decoration: none;
    padding: 10px 20px;
    font-size: 16px;
    background-color: #b38b59;
    color: #ffffff !important; 
    border: none;
    cursor: pointer;
    text-transform: uppercase;
    font-weight: bold;
    border-radius: 4px;
    transition: all 0.3s ease;
  }

  .version-btn:hover {
    background-color: #926f43;
    color: #ffffff;
  }

  @media screen and (max-width: 1240px) {
    .perfect-matches-block {
      max-width: 95%;
    }
  }

function showTab(evt, id) {
  document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById(id).style.display = 'block';
  evt.currentTarget.classList.add('active');
}

