function showTab(evt, id) {
  document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById(id).style.display = 'block';
  evt.currentTarget.classList.add('active');
}

document.addEventListener('DOMContentLoaded', () => {
  const basePrice = 1700; 
  const baseProductName = "Gerbera Sound Lira Multibit DAC"; 
  const priceEl = document.getElementById('main-price');
  const nameEl = document.getElementById('tilda-product-name');
  const discountMsg = document.getElementById('bundle-discount-msg');

  function updateCartData() {
    let totalOptionsPrice = 0;
    let selectedOptions = [];
    let bundleItems = document.querySelectorAll('.bundle-item');
    let allBundleChecked = bundleItems.length > 0;
    bundleItems.forEach(item => { if (!item.checked) allBundleChecked = false; });

    document.querySelectorAll('.price-item:checked').forEach(checkedItem => {
      totalOptionsPrice += parseInt(checkedItem.getAttribute('data-price'), 10) || 0;
      let optionText = checkedItem.parentElement.textContent.trim();
      if(optionText !== "No options" && !checkedItem.classList.contains('bundle-item')) {
           selectedOptions.push(optionText);
      }
    });

    let finalPrice = basePrice + totalOptionsPrice;
    let bundleDiscountText = "";
    if (allBundleChecked) {
      finalPrice = Math.round(finalPrice * 1);
      bundleDiscountText = " (5% Bundle Discount Applied)";
      if (discountMsg) { discountMsg.classList.add('active-discount'); discountMsg.innerHTML = "<b>5% Bundle Discount</b> was successfully applied to total!"; }
    } else {
      if (discountMsg) { discountMsg.classList.remove('active-discount'); discountMsg.innerHTML = "Add recommended synergy components to get <b>5% OFF</b> your total order."; }
    }

    if (priceEl) priceEl.innerText = finalPrice;
    if (nameEl) nameEl.innerText = baseProductName + (selectedOptions.length > 0 ? " [" + selectedOptions.join(', ') + "]" : " (Standard Edition)") + bundleDiscountText;
  }

  updateCartData();
  document.querySelectorAll('.price-item').forEach(item => item.addEventListener('change', updateCartData));

  const buyBtn = document.querySelector('.buy-btn');
  if (buyBtn) {
    buyBtn.addEventListener('click', function() {
      if (typeof gtag === 'function') {
        gtag('event', 'buy_now_click', { 'event_category': 'ecommerce', 'event_label': 'Button Buy Now', 'value': parseInt(priceEl.innerText) || basePrice });
      }
    });
  }
});
