document.addEventListener('DOMContentLoaded', () => {
  const basePrice = 500;
  const baseProductName = 'German Magistro Custom Cable';

  const priceEl = document.getElementById('main-price');
  const nameEl = document.getElementById('tilda-product-name');

  function updateCartData() {
    let totalOptionsPrice = 0;
    let selectedOptions = [];
    let dynamicBaseCablePrice = 100;

    const selectedModel = document.querySelector('input[name="cmodel-opt"]:checked');
    if (selectedModel) {
        dynamicBaseCablePrice = parseInt(selectedModel.getAttribute('data-price'), 10) || 100;
    }

    const priceIncrementPer12cm = dynamicBaseCablePrice * 0.10; 

    document.querySelectorAll('.price-item:checked').forEach(checkedItem => {
      totalOptionsPrice += parseInt(checkedItem.getAttribute('data-price'), 10) || 0;
      let optionText = checkedItem.parentElement.textContent.trim();

      if(!optionText.includes("No connectors")) {
           selectedOptions.push(optionText.replace('Stock: ', ''));
      }
    });

    const selectedCableType = document.querySelector('input[name="cable-len-type"]:checked');
    if (selectedCableType && selectedCableType.value === 'custom') {
      document.getElementById('slider-wrapper').style.display = 'block'; 
      let currentLength = parseFloat(document.getElementById('length-slider').value);
      document.getElementById('length-display').innerText = currentLength.toFixed(2);

      let extraSteps = currentLength > 1.20 ? Math.round((currentLength - 1.20) / 0.12) : 0;
      let extraLengthCost = extraSteps * priceIncrementPer12cm;

      document.getElementById('length-price-display').innerText = extraLengthCost.toFixed(0); 
      totalOptionsPrice += extraLengthCost; 

      if (currentLength !== 1.20) {
          selectedOptions.push(`Length: ${currentLength.toFixed(2)}m`);
      }
    } else {
      document.getElementById('slider-wrapper').style.display = 'none'; 
      document.getElementById('length-price-display').innerText = "0";
    }

    if (priceEl) {
        priceEl.innerText = basePrice + Math.round(totalOptionsPrice);
    }

    if (nameEl) {
        nameEl.innerText = selectedOptions.length > 0 ? `${baseProductName} [${selectedOptions.join(' | ')}]` : `${baseProductName} (Standard 1.20m)`;
    }
  }

  document.querySelectorAll('.price-item, input[name="cable-len-type"], #length-slider').forEach(el => el.addEventListener('change', updateCartData));
  document.getElementById('length-slider').addEventListener('input', updateCartData);

  updateCartData();

const buyBtn = document.querySelector('.buy-btn');

  if (buyBtn) {
    buyBtn.addEventListener('click', function() {
      // Отправка события в Google Analytics 4
      if (typeof gtag === 'function') {
        gtag('event', 'buy_now_click', {
          'event_category': 'ecommerce',
          'event_label': 'Button Buy Now',
          'value': parseInt(priceEl.innerText) || basePrice
        });
      }
    });
  }
  // ==========================================
});
