function showTab(evt, id) {
  document.querySelectorAll('.tab-content').forEach(el => el.style.display = 'none');
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById(id).style.display = 'block';
  evt.currentTarget.classList.add('active');
}

document.addEventListener('DOMContentLoaded', () => {
  const basePrice = 25000; 
  const baseProductName = "Perun Elder Floorstanding Electrostatic Two-way Open Full-range Active Loudspeakers"; 

  const priceEl = document.getElementById('main-price');
  const nameEl = document.getElementById('tilda-product-name');
 const discountMsg = document.getElementById('bundle-discount-msg');

  function updateCartData() {
    let totalOptionsPrice = 0;
    let selectedOptions = [];

        // Проверка, выбраны ли ВСЕ товары из блока связки
    let bundleItems = document.querySelectorAll('.bundle-item');
    let allBundleChecked = bundleItems.length > 0;

    bundleItems.forEach(item => {
      if (!item.checked) allBundleChecked = false;
    });


    document.querySelectorAll('.price-item:checked').forEach(checkedItem => {
      totalOptionsPrice += parseInt(checkedItem.getAttribute('data-price'), 10) || 0;

      let optionText = checkedItem.parentElement.textContent.trim();

      if(optionText !== "Stock internal component wiring configuration (+$0)" && !optionText.includes("(+$0)")) {
         let cleanText = optionText.split('(+$')[0].trim();
         selectedOptions.push(cleanText);
      }
    });

        let finalPrice = basePrice + totalOptionsPrice;
    let bundleDiscountText = "";

    // Применяем скидку 5%, если собрана вся связка
    if (allBundleChecked) {
      finalPrice = Math.round(finalPrice * 1);
      bundleDiscountText = " (5% Bundle Discount for EACH added device Applied)";
      if (discountMsg) {
        discountMsg.classList.add('active-discount');
        discountMsg.innerHTML = "<b>5% Bundle Discount for EACH added device successfully applied!";
      }
    } else {
      if (discountMsg) {
        discountMsg.classList.remove('active-discount');
        discountMsg.innerHTML = "Add recommended synergy components to get <b>5% OFF for EACH added device.";
      }
    }

    if (priceEl) {
      priceEl.innerText = finalPrice;
    }

    if (nameEl) {
      if (selectedOptions.length > 0) {
        nameEl.innerText = baseProductName + " [" + selectedOptions.join(', ') + "]" + bundleDiscountText;
      } else {
        nameEl.innerText = baseProductName + " (Standard Edition)";
      }
    }
  }
  updateCartData();


  document.querySelectorAll('.price-item').forEach(item => {
    item.addEventListener('change', updateCartData);
  });
  // === КОД ДЛЯ ОТПРАВКИ СОБЫТИЙ АНАЛИТИКИ ===
  const buyBtn = document.querySelector('.buy-btn');

  if (buyBtn) {
    buyBtn.addEventListener('click', function() {

      // 1. Яндекс.Метрика
      // ВНИМАНИЕ: Замените XXXXXXXX на номер вашего счетчика Метрики
      if (typeof ym === 'function') {
        ym(XXXXXXXX, 'reachGoal', 'buy_now_click');
      }

      // 2. Google Analytics 4 (gtag)
      // Отправка стандартного события клика по кнопке
      if (typeof gtag === 'function') {
        gtag('event', 'buy_now_click', {
          'event_category': 'ecommerce',
          'event_label': 'Button Buy Now',
          'value': parseInt(priceEl.innerText) || basePrice // опционально передаем текущую цену
        });
      }

    });
  }
  // ==========================================
});
